"""Short dataset labels and auto-generated "chips".

Dataset names tend to grow into sentences ("KCl/water clusters (8 A) from 18 PET-MAD-S MDs
/ r2SCAN vacuum (ORCA)") because they have to carry the method. The chips carry the
method instead — derived from facets that are already stored — so a short ``label``
("KCl/water clusters 8 A") is enough to tell datasets apart.
"""

from __future__ import annotations

import re

from sqlalchemy import select
from sqlalchemy.orm import Session

from ..db.models import Dataset
from .context import AtomDB
from .facets import CLASSICAL_ENGINES

#: tag kind (services/tags.py) → chip kind; "free" tags get no chip
TAG_CHIPS = {"system": "system", "project": "project", "quality": "warn"}
DATA_TYPE_TEXT = {"mlip-md": "MLIP labels", "classical-md": "FF labels", "other": None}
LABEL_MAX = 64


def _short_model(name: str) -> str:
    name = re.sub(r"\s*\([^)]*\)", "", name).strip()  # drop "(May 2026)" etc.
    return name if len(name) <= 24 else name[:23] + "…"


def _frames(n: int | None) -> str:
    if n is None:
        return "? fr"
    if n >= 1_000_000:
        return f"{n / 1e6:.1f}M fr"
    if n >= 10_000:
        return f"{n / 1e3:.0f}k fr"
    if n >= 1000:
        return f"{n / 1e3:.1f}k fr"
    return f"{n} fr"


def _num(v: str) -> str:
    try:
        return f"{float(v):g}"
    except ValueError:
        return v


GEOMETRY_TEXT = {"pbc": "PBC", "no-pbc": "no PBC", "partial-pbc": "partial PBC",
                 "mixed": "mixed PBC"}


def chips(ds: Dataset, facets: dict[str, list[str]], elements: list[str]) -> list[dict]:
    """Compact, ordered description: system · geometry · generator · labels · size · warnings.

    Each chip is ``{"kind": ..., "text": ..., "title": ...}``; ``kind`` drives the colour.
    """
    out: list[dict] = []
    tags = sorted(ds.tags, key=lambda t: t.name.lower())
    for t in tags:
        if t.kind == "system":
            out.append({"kind": "system", "text": t.name, "title": t.description or "system tag"})

    geometry = (facets.get("geometry") or ["unknown"])[0]
    if geometry != "unknown":
        out.append({"kind": "geometry", "text": GEOMETRY_TEXT.get(geometry, geometry),
                    "title": "geometry (from atoms.pbc)"})

    models = sorted(set(facets.get("model", [])))
    engines = sorted({e for e in facets.get("md_engine", []) if e.lower() in CLASSICAL_ENGINES})
    temps = sorted({_num(v) for v in facets.get("temperature", [])}, key=lambda x: float(x)
                   if x.replace(".", "", 1).isdigit() else 0)
    if models:
        # classical force-field names are long and uninformative; the engine says enough
        first = engines[0] if engines and len(models) == 1 else _short_model(models[0])
        text = first + (f" +{len(models) - 1}" if len(models) > 1 else "")
        if temps:
            text += f" · {temps[0]} K" if len(temps) == 1 else f" · {temps[0]}–{temps[-1]} K"
        out.append({"kind": "generator", "text": text,
                    "title": "generated by: " + "; ".join(models)})

    data_type = (facets.get("data_type") or [None])[0]
    funcs = sorted(set(facets.get("functional", [])))
    codes = sorted(set(facets.get("dft_code", []) or facets.get("code", [])))
    if data_type == "dft" or funcs:
        disp = sorted({d for d in facets.get("dispersion", []) if d != "none"})
        method = "/".join(funcs) or "DFT"
        if disp:
            method += "-" + "/".join(disp)
        bits = [method, "/".join(codes)]
        out.append({"kind": "labels", "text": " · ".join(b for b in bits if b),
                    "title": "reference labels"})
    elif not (ds.has_energy or ds.has_forces):
        out.append({"kind": "warn", "text": "unlabelled", "title": "no energies/forces"})
    elif DATA_TYPE_TEXT.get(data_type or ""):
        out.append({"kind": "labels", "text": DATA_TYPE_TEXT[data_type],
                    "title": "labels come from a model, not DFT"})

    out.append({"kind": "size", "text": _frames(ds.n_frames),
                "title": f"{ds.n_frames} frames, {ds.n_atoms_min}–{ds.n_atoms_max} atoms"})
    for t in tags:
        if t.kind in ("project", "quality"):
            out.append({"kind": TAG_CHIPS[t.kind], "text": t.name,
                        "title": t.description or f"{t.kind} tag"})
    if ds.status == "removed":
        out.append({"kind": "warn", "text": "removed", "title": "data deleted; record kept"})
    return out


# --------------------------------------------------------------------------- suggestions

_PAREN = re.compile(r"\s*\(([^()]*)\)")


def suggest_label(ds: Dataset, facets: dict[str, list[str]]) -> str:
    """Strip from the name what the chips already say (method after " / ", parentheses
    naming the code/model/functional or a frame count) and truncate."""
    name = ds.name.split(" / ")[0]
    known = {v.lower() for k in ("model", "functional", "code", "dft_code", "md_engine")
             for v in facets.get(k, [])}
    known |= {"orca", "cp2k", "vasp", "gromacs", "vacuum", "pbc", "unlabelled"}

    def keep(m: re.Match) -> str:
        inner = m.group(1).strip()
        low = inner.lower()
        if re.fullmatch(r"[\d.,]+k?", low) or any(k and k in low for k in known):
            return ""
        return m.group(0)

    name = _PAREN.sub(keep, name)
    for m in sorted(known, key=len, reverse=True):
        if len(m) > 3:
            name = re.sub(rf"\b(from|with|on)?\s*\d*\s*{re.escape(m)}s?\b( MDs?)?", "", name,
                          flags=re.IGNORECASE)
    name = re.sub(r"\s+([,;])", r"\1", re.sub(r"\s{2,}", " ", name)).strip(" ,;:-·")
    if len(name) > 48:
        name = name[:47].rstrip(" ,;") + "…"
    return name or ds.name[:48]


def suggest_labels(s: Session, only_missing: bool = True) -> list[dict]:
    from .search import facets_for

    dss = list(s.execute(select(Dataset).order_by(Dataset.id)).scalars())
    facets = facets_for(s, [d.id for d in dss])
    out = []
    for d in dss:
        if only_missing and d.label:
            continue
        out.append({"id": d.id, "name": d.name, "label": d.label,
                    "suggested": suggest_label(d, facets[d.id])})
    return out


def apply_labels(s: Session, labels: dict[str, str]) -> list[str]:
    from .edit import edit_node

    changed = []
    for ds_id, label in labels.items():
        if edit_node(s, ds_id, label=label):
            changed.append(ds_id)
    AtomDB.audit(s, "labels.apply", None, n=len(changed))
    return changed
